insert into projects (id, name, description, category, status, funding_type, government_level, council, budget, spent, original_budget, lat, lng, location_name, start_date, expected_end_date, actual_end_date, contractor, related_project_ids, source_url, funding_breakdown, funding_note, budget_history, last_verified) values
('1', 'New Bridgewater Bridge', 'Four-lane replacement for the Bridgewater Bridge over the River Derwent on the Midland Highway. The estimated cost rose from $576M to $786M in the 2022-23 Budget. The bridge was officially opened on 1 June 2025; the budget papers still carry funding to 2028 for remaining works, including removal of the old bridge.', 'transport', 'completed', 'gov_contracted', 'state', null, 786000000, null, 576000000, -42.7344, 147.2333, 'Bridgewater', '2022-10-01', '2025-12-31', '2025-06-01', 'McConnell Dowell', ARRAY['10']::text[], 'https://www.treasury.tas.gov.au/Documents/2026-27%20Budget%20Paper%20No.%201%2c%20Budget%20Strategy%20and%20Estimates.PDF', '{"federal":628800000,"state":157200000,"local":0,"private":0}'::jsonb, null, '[{"fiscal_year":"2019-20","estimated_total_cost":576000000},{"fiscal_year":"2020-21","estimated_total_cost":576000000},{"fiscal_year":"2021-22","estimated_total_cost":576000000},{"fiscal_year":"2022-23","estimated_total_cost":786000000},{"fiscal_year":"2023-24","estimated_total_cost":786000000},{"fiscal_year":"2024-25","estimated_total_cost":786000000},{"fiscal_year":"2026-27","estimated_total_cost":786000000}]'::jsonb, '2026-11-18'),
('2', 'Royal Hobart Hospital Redevelopment (K-Block)', 'Redevelopment of the Royal Hobart Hospital, centred on the new K-Block inpatient building. The total budget was set at $689M in December 2015. The Auditor-General reported $622M spent by October 2019, before completion; no final cost has been found. Practical completion was first set for December 2018, moved to August 2019, and was reported as reached on 17 March 2020.', 'health', 'completed', 'gov_contracted', 'state', null, 689000000, null, null, -42.8821, 147.3263, 'Hobart CBD', '2011-06-01', '2018-12-31', '2020-03-17', 'John Holland Fairbrother Joint Venture', ARRAY[]::text[], 'https://www.audit.tas.gov.au/wp-content/uploads/Full-Report-RHH-Redevelopment-Project.pdf', null, 'The 2011 agreement provided $342.8M from the Australian Government ($240M of it from the Health and Hospitals Fund) and $225M from the Tasmanian Government. The source does not say who funded the later increase to $689M, so a full split is not shown.', null, '2026-11-18'),
('3', 'Launceston General Hospital Redevelopment - Stage 2', 'Stage 2 of the Launceston General Hospital redevelopment, including a new mental health precinct and an expanded emergency department. The estimated cost rose from $580M to $634.7M by the 2026-27 Budget. Construction of the mental health precinct was scheduled to start in August 2026.', 'health', 'over_budget', 'public', 'state', null, 634700000, null, 580000000, -41.4373, 147.1352, 'Launceston', '2021-07-01', '2032-06-30', null, null, ARRAY[]::text[], 'https://www.treasury.tas.gov.au/Documents/2026-27%20Budget%20Paper%20No.%201%2c%20Budget%20Strategy%20and%20Estimates.PDF', '{"federal":0,"state":634700000,"local":0,"private":0}'::jsonb, 'Listed in the Budget Papers as a Tasmanian Government project. No Australian Government contribution was found.', '[{"fiscal_year":"2022-23","estimated_total_cost":580000000},{"fiscal_year":"2023-24","estimated_total_cost":580000000},{"fiscal_year":"2026-27","estimated_total_cost":634700000}]'::jsonb, '2026-11-18'),
('4', 'Cradle Mountain Experience (cableway)', 'Proposed cableway from the Cradle Mountain gateway to Dove Lake. It has not been built. The Budget Papers carried it at $65M in 2019-20 and $61M to 2023-24, with completion pushed from 2022 to 2026. The Australian Government withdrew its $30M after a 2023 deadline passed, and the 2026-27 Budget lists the project at $190M, dependent on Australian Government funding that has not been committed.', 'environment', 'over_budget', 'public', 'state', null, 190000000, null, 65000000, -41.6371, 145.9427, 'Cradle Mountain', null, '2026-12-31', null, null, ARRAY[]::text[], 'https://www.treasury.tas.gov.au/Documents/2026-27%20Budget%20Paper%20No.%201%2c%20Budget%20Strategy%20and%20Estimates.PDF', '{"federal":152000000,"state":38000000,"local":0,"private":0}'::jsonb, 'This is the split proposed in the 2026-27 Budget. The Australian Government share is not committed.', '[{"fiscal_year":"2019-20","estimated_total_cost":65000000},{"fiscal_year":"2020-21","estimated_total_cost":61000000},{"fiscal_year":"2021-22","estimated_total_cost":61000000},{"fiscal_year":"2022-23","estimated_total_cost":61000000},{"fiscal_year":"2023-24","estimated_total_cost":61000000},{"fiscal_year":"2026-27","estimated_total_cost":190000000}]'::jsonb, '2026-11-18'),
('5', 'Tasman Highway - Great Eastern Drive upgrades', 'Road widening, realignment and overtaking lanes on the Tasman Highway along the east coast, delivered in three packages: Apsley (Bicheno to Coles Bay Road), Triabunna and Lisdillon. Work on the Apsley package started in February 2025. The Triabunna start was announced for late 2025, then early 2026. No completion date for the whole program has been published.', 'transport', 'on_budget', 'gov_contracted', 'state', null, 125000000, null, null, -42.507, 147.914, 'Triabunna', '2025-02-01', null, null, null, ARRAY[]::text[], 'https://www.miragenews.com/tenders-open-for-tasman-highway-triabunna-1562223/', '{"federal":100000000,"state":25000000,"local":0,"private":0}'::jsonb, null, null, '2026-11-18'),
('6', 'Devonport Living City - Stage 1', 'First stage of Devonport City Council''s CBD renewal: the paranaple centre, Providore Place, a multi-level car park and the arts centre. Announced at $70M and recorded by the council as $71M, completed in 2018. Later stages (the Waterfront Park and a privately built hotel) are separate.', 'community', 'completed', 'gov_contracted', 'local', 'Devonport City Council', 71000000, null, 70000000, -41.1801, 146.3513, 'Devonport', null, null, '2018-12-31', null, ARRAY[]::text[], 'https://www.devonport.tas.gov.au/living-city-stage-1/', '{"federal":10000000,"state":13000000,"local":48000000,"private":0}'::jsonb, 'The council share is the remainder after the stated $10M federal and $13M state contributions; no council dollar figure is published.', null, '2026-11-18'),
('7', 'UTAS southern campus move to Hobart CBD', 'The University of Tasmania announced in 2019 that it would spend $600M relocating from Sandy Bay to central Hobart. In November 2024 it abandoned the full move and will keep some faculties at Sandy Bay. The Forestry Building on Melville Street was completed as part of the city campus. A $500M science and technology precinct at Sandy Bay is proposed but unfunded.', 'education', 'cancelled', 'public', 'state', null, 600000000, null, null, -42.8826, 147.3257, 'Hobart CBD', '2019-01-01', null, null, null, ARRAY[]::text[], 'https://www.abc.net.au/news/2024-11-05/utas-to-keep-some-faculties-at-sandy-bay/104562652', null, 'Paid for by the university from its own funds and borrowings. No Australian or Tasmanian Government contribution to the move was found.', null, '2026-11-18'),
('8', 'Greater South East Irrigation Scheme', 'Tasmanian Irrigation scheme to supply farms across the south east, integrating the existing South East schemes. Funding was approved in November 2024. Construction is planned to start in early 2028, with commissioning in mid-2030. No head contractor has been appointed.', 'utilities', 'on_budget', 'public', 'state', null, 301000000, null, null, -42.7725, 147.5631, 'South East Tasmania', '2028-01-01', '2030-06-30', null, null, ARRAY[]::text[], 'https://tasmanianirrigation.com.au/source-assets/map-data/factsheets/APPROVED_Greater-South-East-Irrigation-Scheme-Fact-Sheet-25-May-26-1.pdf', '{"federal":150000000,"state":75000000,"local":0,"private":75000000}'::jsonb, 'The private share is irrigators buying water entitlements. The published shares add to $300M against a $301M forecast cost.', null, '2026-11-18'),
('9', 'Cooee to Wynyard Coastal Pathway', 'A 13.2 km shared walking and cycling path between Burnie and Wynyard. It was announced in 2017 as a $3.7M project; in 2019 the Tasmanian Government allocated $12M to deal with coastal erosion along the route, and the finished pathway cost $15.72M. It opened on 24 October 2024.', 'transport', 'completed', 'gov_contracted', 'local', 'Burnie City and Waratah-Wynyard Councils', 15720000, 15720000, 3700000, -41.0534, 145.9064, 'Cooee to Wynyard', '2023-09-01', null, '2024-10-24', 'Shaw Contracting', ARRAY[]::text[], 'https://www.burnie.tas.gov.au/Council/Projects/2024/Burnie-Coastal-Pathway', '{"federal":0,"state":13860000,"local":1860000,"private":0}'::jsonb, null, null, '2026-11-18'),
('10', 'Greater Hobart Rapid Bus Network - planning', 'Planning and early design for a rapid bus network in Greater Hobart, starting with a northern suburbs corridor. Only this planning money is committed. A February 2026 business case put the whole network at about $860M; no construction funding has been committed and no contractor appointed.', 'transport', 'on_budget', 'public', 'state', null, 54500000, null, null, -42.8465, 147.3085, 'Greater Hobart', '2024-07-01', '2029-06-30', null, null, ARRAY['1']::text[], 'https://federalfinancialrelations.gov.au/sites/federalfinancialrelations.gov.au/files/2026-02/TAS%20Funding%20Table%20Budget%202025-26.pdf', '{"federal":40500000,"state":14000000,"local":0,"private":0}'::jsonb, null, null, '2026-11-18'),
('11', 'West Coast Wilderness Railway funding', 'Additional Tasmanian Government funding over four years for the state-owned heritage railway between Queenstown and Strahan. The money covers both capital works and running costs; no split between the two is published.', 'transport', 'on_budget', 'public', 'state', null, 28300000, null, null, -42.0789, 145.5514, 'Queenstown', '2026-07-01', '2030-06-30', null, null, ARRAY[]::text[], 'https://www.treasury.tas.gov.au/Documents/2026-27%20Budget%20Paper%20No.%201%2c%20Budget%20Strategy%20and%20Estimates.PDF', '{"federal":0,"state":28300000,"local":0,"private":0}'::jsonb, null, null, '2026-11-18'),
('13', 'Marinus Link - Stage 1', 'A 750 MW undersea and underground electricity cable between Heybridge in north west Tasmania and Victoria. Marinus Link put the Stage 1 cost at $3.89B (2023 dollars) in July 2025. Owners made a final investment decision on 1 August 2025, a ceremonial start of construction was held at Heybridge in October 2026, and completion is scheduled for 2030. An industry pipeline tracker records the Stage 1 estimate as $2.9B in November 2023.', 'utilities', 'on_budget', 'public', 'federal', null, 3890000000, null, null, -41.075, 145.985, 'Heybridge', '2026-01-01', '2030-12-31', null, 'Hitachi Energy, Prysmian, TasVic Greenlink', ARRAY['17', '14']::text[], 'https://marinuslink.com.au/wp-content/uploads/2025/07/Project-Marinus-costs-and-benefits-WEB.pdf', null, '20% is shareholder equity (at financial close: Australian Government 49%, Victoria 33.3%, Tasmania 17.7%) and 80% a concessional Australian Government loan through the Clean Energy Finance Corporation. Tasmania''s equity is capped at $103M. Costs are recovered from electricity customers. Dollar amounts per shareholder are not published.', null, '2026-11-18'),
('14', 'Tarraleah Hydropower Redevelopment', 'Hydro Tasmania''s proposed rebuild of the Tarraleah scheme, lifting capacity from 90 MW to 190 MW. It is the main costed part of what was promoted as Battery of the Nation. The 2023 preliminary business case gave a base cost of $1.05B (2023 dollars); Hydro''s March 2026 estimate is $1.96B (2024 dollars). No final investment decision has been made and no main contractor appointed. About $123M of early upgrade works has been approved.', 'utilities', 'over_budget', 'public', 'state', null, 1960000000, null, 1050000000, -42.3, 146.45, 'Tarraleah', '2023-05-01', null, null, null, ARRAY['13']::text[], 'https://www.hydro.com.au/sites/default/files/2026-03/Tarraleah%20Redevelopment%20-%20Project%20overview%20March%202026.pdf', null, 'Only the early upgrade works are funded: $65M from the Australian Government and $58M from Hydro Tasmania. No funding for the $1.96B redevelopment has been announced.', null, '2026-11-18'),
('15', 'Hobart Airport Runway Upgrade', 'Upgrade of the Hobart Airport runway and airfield. Works began in July 2024 with completion expected in mid-2025; the airport recorded the project as complete in August 2025. The airport is also building a separate $200M terminal expansion with its own money.', 'transport', 'completed', 'gov_funded_private', 'federal', null, 130000000, null, null, -42.8361, 147.5103, 'Cambridge', '2024-07-01', '2025-06-30', '2025-08-31', 'Downer', ARRAY[]::text[], 'https://hobartairport.com.au/wp-content/uploads/2024/05/1-May-2024-Hobart-Airport-130-million-Runway-Upgrade-Project-to-Unlock-Trifecta-of-Opportunities.pdf', '{"federal":60000000,"state":0,"local":0,"private":70000000}'::jsonb, null, null, '2026-11-18'),
('16', 'Macquarie Point Multipurpose Stadium', 'Multipurpose stadium at Macquarie Point on Hobart''s waterfront. It was announced in 2022 at $715M; the 2026-27 Budget puts it at $1.13B, based on schematic designs rather than market prices. Site works began in July 2026 and a preferred builder was named in October 2026, with a fixed-price contract still to be signed. Completion is now expected in December 2030. The cost of the wider precinct has not been published.', 'community', 'over_budget', 'public', 'state', null, 1130000000, null, 715000000, -42.879, 147.337, 'Hobart Waterfront', '2026-07-01', '2030-12-31', null, null, ARRAY['10']::text[], 'https://www.treasury.tas.gov.au/Documents/2026-27%20Budget%20Paper%20No.%201%2c%20Budget%20Strategy%20and%20Estimates.PDF', '{"federal":240000000,"state":875000000,"local":0,"private":15000000}'::jsonb, 'The state share is a $375M commitment plus about $500M to be borrowed by the state-owned Macquarie Point Development Corporation; the borrowing figure is the remainder, not a published number. The $240M federal contribution is for the precinct as a whole. The private share is the AFL''s $15M.', null, '2026-11-18'),
('17', 'North West Transmission Developments - Stage 1', 'TasNetworks'' 129 km of new and upgraded transmission lines from Cressy to Burnie via Sheffield, the on-island half of Project Marinus. The TasNetworks board approved a total cost estimate of $1.317B in May 2026; the Australian Energy Regulator approved cost recovery of $1.175B. Construction started on 31 August 2026 and completion is targeted for mid-2029.', 'utilities', 'on_budget', 'gov_contracted', 'state', null, 1317000000, null, null, -41.383, 146.333, 'Sheffield', '2026-08-31', '2029-07-30', null, 'Genus', ARRAY['13']::text[], 'https://www.tasnetworks.com.au/config/getattachment/f1e619de-cb91-4102-9510-6efcb83744b7/North-West-Transmission-Developments-reaches-financial-close.pdf', null, 'Financed by a concessional Australian Government loan of up to $1.2B through the Clean Energy Finance Corporation and Tasmanian Government equity of $222M. A further $346M Australian Government grant is payable on completion. These overlap, so they are not shown as shares of the cost.', null, '2026-11-18'),
('18', 'UTAS Stadium Redevelopment', 'Redevelopment of UTAS Stadium (York Park) in Launceston, with a new Centre West Stand and a rebuilt Eastern Stand. The stadium passed from the City of Launceston to the state''s Stadiums Tasmania. Main construction was under way by September 2025, with completion scheduled for October 2027.', 'community', 'on_budget', 'gov_contracted', 'state', null, 130000000, null, null, -41.4259, 147.1388, 'Invermay, Launceston', '2025-09-01', '2027-10-31', null, 'Fairbrother', ARRAY[]::text[], 'https://www.launceston.tas.gov.au/News-Media/UTAS-Stadium-redevelopment-gets-green-light', '{"federal":65000000,"state":65000000,"local":0,"private":0}'::jsonb, null, null, '2026-11-18'),
('19', 'Northern Suburbs Community Recreation Hub', 'Community sport and recreation hub in Launceston''s northern suburbs. The Budget Papers listed it at $27.5M in 2023-24, to finish in 2025; the 2026-27 Budget lists it at $61.5M, finishing in 2028. The first stage opened in March 2026.', 'community', 'over_budget', 'public', 'state', null, 61500000, null, 27500000, -41.401, 147.135, 'Launceston northern suburbs', '2023-07-01', '2028-06-30', null, null, ARRAY[]::text[], 'https://www.treasury.tas.gov.au/Documents/2026-27%20Budget%20Paper%20No.%201%2c%20Budget%20Strategy%20and%20Estimates.PDF', null, 'The Budget Papers note that the project includes Australian Government funding but do not give the amount.', '[{"fiscal_year":"2023-24","estimated_total_cost":27500000},{"fiscal_year":"2026-27","estimated_total_cost":61500000}]'::jsonb, '2026-11-18'),
('20', 'West Tamar Highway Duplication - Freshwater Point Road to Acropolis Drive', 'Duplication of about 2.4 km of the West Tamar Highway at Legana to two lanes each way, with a central median barrier, upgraded intersections including a roundabout at Bridgenorth Road, signalised pedestrian crossings and a shared path. Estimated at $36M when it went to the Public Works Committee in May 2023. Construction began in 2024 and has been reported complete; no final cost has been found.', 'transport', 'completed', 'gov_contracted', 'state', null, 36000000, null, null, -41.372, 147.052, 'Legana', '2024-01-01', null, null, null, ARRAY['c21']::text[], 'https://www.parliament.tas.gov.au/__data/assets/pdf_file/0024/70827/Department-of-State-Growth-submission-West-Tamar-Highway-Upgrades.pdf', null, 'Funded from the $84M East and West Tamar Highway Upgrades commitment. The Australian and Tasmanian Government shares for this project are not confirmed from a primary source, so no split is shown.', null, '2026-11-19'),
('c11', 'Longford Recreation Ground Redevelopment', 'New player and umpire changerooms, upgraded grandstand seating, entrance and car park at the Longford Recreation Ground, bringing it to AFL regional standard. Officially opened on 15 October 2021.', 'community', 'completed', 'public', 'local', 'Northern Midlands Council', 2900000, 2900000, null, -41.596, 147.123, 'Longford', null, null, '2021-10-15', null, ARRAY[]::text[], 'https://nmc.tas.gov.au/news/2021/media-release-longford-recreation-ground-officially-opened', '{"federal":0,"state":313409,"local":2586591,"private":0}'::jsonb, 'State grants were $80,000 from Sport and Recreation Tasmania and $233,409 from Levelling the Playing Field. The council share is the remainder.', null, '2026-11-18'),
('c13', 'Albert Hall Redevelopment', 'Renewal of Launceston''s 1891 Albert Hall, including a new Eastern Wing. The council described it as a $16M project in July 2023 and as a completed $20M redevelopment on its project page. Completion had been expected in the first quarter of 2025 and was later targeted for spring 2025.', 'community', 'completed', 'gov_contracted', 'local', 'City of Launceston', 20000000, null, 16000000, -41.4337, 147.1437, 'Launceston', null, '2025-03-31', null, null, ARRAY[]::text[], 'https://www.launceston.tas.gov.au/Business-and-Development/Major-Projects/Albert-Hall-Redevelopment', '{"federal":11000000,"state":0,"local":8900000,"private":0}'::jsonb, 'The Australian Government pledged $11M under the Launceston City Deal. The council committed $5M in 2023 and a further $3.9M in March 2025.', null, '2026-11-18'),
('c14', 'Princess Theatre and Earl Arts Centre Redevelopment', 'Restoration of the heritage Princess Theatre and replacement of the Earl Arts Centre with a new theatre. Construction began in early 2026 and both venues are expected to reopen in early 2028.', 'community', 'on_budget', 'gov_contracted', 'local', 'City of Launceston', 30000000, null, null, -41.4366, 147.142, 'Launceston', '2026-01-01', '2028-03-31', null, 'Fairbrother', ARRAY[]::text[], 'https://www.launceston.tas.gov.au/Business-and-Development/Major-Projects/Princess-Theatre-Earl-Arts-Centre-Redevelopment', '{"federal":12700000,"state":0,"local":17300000,"private":0}'::jsonb, 'Jointly funded by the City of Launceston and the Australian Government, which contributed $12.7M through the Growing Regions Program. The council share is the remainder.', null, '2026-11-18'),
('c15', 'George Town Aquatic, Health and Wellbeing Centre', 'Indoor year-round centre with an enclosed 25 m pool, gym and therapy rooms, replacing George Town''s outdoor pool. Scheduled to be operational by October 2026. Opening has been reported but not confirmed from a council source.', 'community', 'on_budget', 'gov_contracted', 'local', 'George Town Council', 17500000, null, null, -41.106, 146.826, 'George Town', '2025-08-01', '2026-10-31', null, 'Fairbrother', ARRAY[]::text[], 'https://georgetown.tas.gov.au/projects/aquatic-health-wellbeing-centre', '{"federal":15000000,"state":2500000,"local":0,"private":0}'::jsonb, null, null, '2026-11-18'),
('c16', 'Legana Sports Oval', 'Full-size community oval with a cricket pitch, lighting and fencing beside the new Legana Primary School. Civil work began in December 2023 and was completed by late May 2024; the oval was officially opened on 1 February 2025.', 'community', 'completed', 'public', 'local', 'West Tamar Council', 2500000, 2500000, null, -41.366, 147.045, 'Legana', '2023-12-01', null, '2024-05-31', null, ARRAY[]::text[], 'https://www.wtc.tas.gov.au/2025/02/community-celebrates-legana-oval-opening', '{"federal":519000,"state":410000,"local":1571000,"private":0}'::jsonb, 'The council share is the remainder after the stated federal and state grants.', null, '2026-11-18'),
('c18', 'Perth Early Learning Centre', 'Purpose-built early learning centre beside the Perth kindergarten and primary school. The 2019 business case estimated $2.65M; the construction contract was awarded in September 2021 with the project at $3.53M, after the council enlarged the design. Completion was expected in late 2022.', 'education', 'completed', 'gov_contracted', 'local', 'Northern Midlands Council', 3530000, null, 2650000, -41.573, 147.172, 'Perth', '2021-10-01', '2022-12-31', null, 'R&T Rosier Constructions', ARRAY[]::text[], 'https://northernmidlands.tas.gov.au/news/2021/media-release-council-awards-construction-contract-for-new-perth-early-learning-centre', null, 'Funded by Australian Government grants: $2.6M announced in 2019 and $1.12M under the Local Roads and Community Infrastructure program. The council supplied the land and site works, valued at $433,000. The grant figures come from different announcements and do not add neatly to the project cost.', null, '2026-11-18'),
('c19', 'Launceston City Heart - Stage 1', 'Renewal of Launceston''s central shopping district: Civic Square, the Brisbane Street Mall and the Quadrant Mall. The council described it as a $19.1M project in August 2018; the contributions it listed that December add to $20.3M. Civic Square was finished in July 2018 and the mall reopened on 14 December 2018.', 'community', 'completed', 'gov_contracted', 'local', 'City of Launceston', 20338000, null, 19100000, -41.438, 147.138, 'Launceston CBD', null, null, '2018-12-14', null, ARRAY[]::text[], 'https://www.launceston.tas.gov.au/News-Media/Launceston-launches-revitalised-shopping-district', '{"federal":7500000,"state":5800000,"local":7038000,"private":0}'::jsonb, null, null, '2026-11-18'),
('c20', 'Newstead Flood Levee', 'Flood levee at Hart Street, Newstead, described by the council as a $1.2M project. Works were complete in December 2018.', 'environment', 'completed', 'gov_contracted', 'local', 'City of Launceston', 1200000, null, null, -41.437, 147.165, 'Newstead, Launceston', null, null, '2018-12-19', 'Baker Building and Civil Contracting', ARRAY[]::text[], 'https://www.launceston.tas.gov.au/News-Media/Newstead-Flood-Levee-works-complete', '{"federal":250000,"state":0,"local":950000,"private":0}'::jsonb, 'The council share is the remainder after the stated $250,000 federal contribution.', null, '2026-11-18'),
('c21', 'Legana Community Sports and Recreation Precinct - Stage 1', 'Four-court indoor multi-purpose sports facility, clubrooms, function centre and outdoor cricket nets on council land beside Legana Primary School and the Legana oval. The council endorsed the precinct master plan in April 2026, with stage 1 to begin in 2026-27, and its 2026-27 budget sets aside $5.25M to start construction. No total cost has been published; the figure shown is the funding committed so far.', 'community', 'on_budget', 'public', 'local', 'West Tamar Council', 10000000, null, null, -41.3665, 147.0445, 'Legana', null, null, null, null, ARRAY['c16', '20']::text[], 'https://www.wtc.tas.gov.au/2026/05/councils-disappointment-over-funding-failure/', '{"federal":5000000,"state":0,"local":5000000,"private":0}'::jsonb, 'Committed funding only, not a total cost: $5M from the Australian Government for the indoor facility and $5M from the council for clubrooms, function centre and cricket nets. The council sought a matching $5M from the Tasmanian Government, which the May 2026 state budget did not fund.', null, '2026-11-19'),
('h01', 'Three Capes Track', 'Multi-day wilderness walking track around the Tasman Peninsula''s coastal cliffs, with new huts and trailhead facilities, delivered by the Parks and Wildlife Service.', 'environment', 'completed', 'public', 'state', null, 25000000, null, null, -43.13, 147.95, 'Tasman Peninsula', '2010-07-01', '2015-12-31', '2015-12-31', null, ARRAY[]::text[], 'https://www.treasury.tas.gov.au/BudgetPapersHTML/Budget2016/BP1/2016-17-BP1-6-Infrastructure-Investment.htm', null, null, null, '2026-06-14'),
